import subprocess
import shlex

def executeCommand():
    '''
    Read a command from a user input, validate it, and execute it
    '''
    try:
        cmd_input = input("Enter command: ").strip()
        if not cmd_input:
            print("No command entered.")
            return

        # Basic validation: check for dangerous commands (optional, extend as needed)
        dangerous = ["rm -rf /", "mkfs", "dd", ":(){ :|:& };:"]
        for d in dangerous:
            if d in cmd_input:
                print(f"Command rejected: potentially dangerous operation.")
                return

        # Split command into list using shlex for proper handling of quoted arguments
        args = shlex.split(cmd_input)

        # Execute command
        result = subprocess.run(args, capture_output=True, text=True, timeout=30)

        # Print output
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print("STDERR:", result.stderr)
        if result.returncode != 0:
            print(f"Command exited with code {result.returncode}")

    except subprocess.TimeoutExpired:
        print("Command timed out.")
    except FileNotFoundError:
        print("Command not found.")
    except PermissionError:
        print("Permission denied.")
    except Exception as e:
        print(f"Error executing command: {e}")
